/// A client that connects and never speaks gets the short first-request
/// deadline, not the full idle allowance. At 32 slots the difference is what a
/// trivial flood would exploit.
#[test]
fn a_silent_client_is_dropped_without_holding_a_slot_for_the_whole_lifetime() {
    let Some(f) = fixture() else {
        eprintln!("SKIPPED a_silent_client_is_dropped: openssl is not usable here");
        return;
    };
    let limits = brisk_limits();

    std::thread::scope(|scope| {
        scope.spawn(|| {
            let (stream, peer) = f.listener.accept().expect("accept");
            serve_connection(stream, peer, &f.server_tls, &f.ctx, limits);
        });

        // Raw TCP, no TLS: connect and say nothing at all.
        let mut sock = std::net::TcpStream::connect(("127.0.0.1", f.port)).expect("connect");
        sock.set_read_timeout(Some(limits.lifetime))
            .expect("timeout");
        let started = std::time::Instant::now();

        // Drain to end of stream. rustls emits a close_notify alert on the way
        // out even though no handshake completed, so the bytes seen here are
        // the shutdown itself; what this test is about is how long it took.
        let mut sink = [0u8; 64];
        loop {
            match sock.read(&mut sink) {
                Ok(0) | Err(_) => break,
                Ok(_) => continue,
            }
        }
        let waited = started.elapsed();

        assert!(
            waited < limits.lifetime / 2,
            "dropped after {waited:?}, which is the idle allowance rather than the \
             first-request deadline"
        );
    });
}

