/// The connection cap: the only thing between a flood and unbounded thread
/// creation. Serialized against the other tests in this file by
/// `LIVE_CONNECTIONS` being process-global, so it restores the counter itself.
#[test]
fn the_connection_cap_admits_up_to_the_limit_and_releases_on_drop() {
    // Nothing else in this binary claims a slot outside an accept loop, and no
    // accept loop runs in tests.
    assert_eq!(
        LIVE_CONNECTIONS.load(std::sync::atomic::Ordering::Acquire),
        0
    );

    SATURATION_LOGGED.store(false, std::sync::atomic::Ordering::Release);

    let mut slots: Vec<_> = (0..MAX_CONNECTIONS)
        .map(|i| claim_slot().unwrap_or_else(|| panic!("slot {i} should be admitted")))
        .collect();
    assert!(
        claim_slot().is_none(),
        "the {MAX_CONNECTIONS}th+1 connection must be refused, not queued"
    );

    // The "at capacity" line is once per episode, and this is what makes that
    // true: at the cap a flood ends one connection and takes its slot again
    // immediately, so re-arming on any release would put a line in the log per
    // refusal — the spam the flag exists to prevent, reached the long way round.
    //
    // Asserted here rather than in a test of its own because `LIVE_CONNECTIONS`
    // is process-global and these run as threads in one process: a second test
    // driving the same counter would race this one.
    assert!(
        SATURATION_LOGGED.load(std::sync::atomic::Ordering::Acquire),
        "the first refusal must arm the notice"
    );
    slots.pop();
    assert!(
        SATURATION_LOGGED.load(std::sync::atomic::Ordering::Acquire),
        "one connection finishing at the cap is not a new saturation episode"
    );
    slots.truncate(SATURATION_REARM_BELOW - 1);
    assert!(
        !SATURATION_LOGGED.load(std::sync::atomic::Ordering::Acquire),
        "coming back below {SATURATION_REARM_BELOW} live connections re-arms it"
    );

    drop(slots);
    assert_eq!(
        LIVE_CONNECTIONS.load(std::sync::atomic::Ordering::Acquire),
        0,
        "every slot must come back, or the cap shrinks for the process lifetime"
    );
    let reopened = claim_slot();
    assert!(
        reopened.is_some(),
        "capacity must be reusable once connections finish"
    );
    drop(reopened);
}

/// The certificate failure has to be reachable BEFORE the singleton claim.
///
/// `--replace` terminates the running daemon as part of claiming, so a
/// certificate that fails to load after that point takes the incumbent down and
/// then aborts, leaving the host with no daemon at all — no refresh, no
/// auto-switch, not merely no listener. `wiki/Daemon.md` recommends
/// `clauth daemon --replace --listen` as the post-`lego renew` hook, so the
/// documented automation is the trigger.
///
/// What this pins is that a bad certificate is discovered in `prepare`, which
/// needs no daemon lock, no config and no scheduler — so `daemon::serve` can
/// call it above the claim, and does.
///
/// The cert directory is pointed at an empty tempdir through `tls.json` rather
/// than relying on this host having no lego tree: the box this was written on
/// serves a real certificate out of `/etc/lego`, which `HomeSandbox` does not
/// redirect, so the obvious version of this test passed vacuously.
#[test]
fn a_missing_certificate_fails_in_prepare_not_after_the_claim() {
    let _home = HomeSandbox::new();
    let empty = tempfile::tempdir().expect("tempdir");
    let tls_json = crate::profile::clauth_dir().expect("dir").join("tls.json");
    #[allow(clippy::expect_used)]
    std::fs::create_dir_all(tls_json.parent().expect("has parent")).expect("mkdir");
    std::fs::write(
        &tls_json,
        serde_json::json!({ "schema": 1, "cert_dir": empty.path() }).to_string(),
    )
    .expect("write tls.json");

    // Matched rather than `expect_err`: that needs `Debug` on the success type,
    // and `Prepared` holds a rustls config — not a thing to
    // give a derived formatter to for a test's convenience.
    let Err(err) = super::prepare(
        "127.0.0.1:0".parse().expect("addr"),
        &crate::daemon::api::tls::CertSource::Lego,
    ) else {
        panic!("an empty certificate directory must fail in prepare");
    };
    let msg = format!("{err:#}");
    assert!(
        msg.contains(&empty.path().display().to_string()),
        "the failure names the path the operator has to fix: {msg}"
    );
}

/// `prepare` reads the certificate and binds nothing: the bind belongs below
/// the singleton claim, where the port is winnable, so a
/// prepared-but-not-yet-serving listener leaves its port answering
/// `ConnectionRefused`. The token mint lives below the claim too — see the
/// tests at the end of this file.
#[test]
fn prepare_leaves_the_port_unbound() {
    let _home = HomeSandbox::new();
    let dir = tempfile::tempdir().expect("tempdir");
    let Some((paths, _ca)) = generate_chain(dir.path()).expect("fixture") else {
        return;
    };
    // A concrete port, picked by binding and dropping: prepare must leave it
    // exactly as free as it found it.
    let probe = std::net::TcpListener::bind("127.0.0.1:0").expect("bind probe");
    let addr = probe.local_addr().expect("addr");
    drop(probe);

    let _prepared = super::prepare(addr, &crate::daemon::api::tls::CertSource::Explicit(paths))
        .expect("a valid certificate prepares");

    let refused = std::net::TcpStream::connect(addr).expect_err("nothing bound the port");
    assert!(
        matches!(refused.kind(), std::io::ErrorKind::ConnectionRefused),
        "prepare must not bind: {refused}"
    );
}

/// The default mode's contract against a live daemon: losing the boot race is
/// the desired end state, so a second `--listen` instance exits 0 rather than
/// dying on the port the incumbent holds. The singleton and the port are held
/// exactly as the incumbent holds them; the bind sits below the claim, so the
/// redundant instance never reaches it.
#[test]
fn a_second_listener_instance_yields_to_the_daemon_holding_the_port() {
    let _home = HomeSandbox::new();
    let certdir = tempfile::tempdir().expect("tempdir");
    let Some((paths, _ca)) = generate_chain(certdir.path()).expect("fixture") else {
        return;
    };
    let incumbent_port = std::net::TcpListener::bind("127.0.0.1:0").expect("bind");
    let addr = incumbent_port.local_addr().expect("addr");
    let dir = crate::profile::clauth_dir().expect("dir");
    // `serve` would create this; the claim has to run before it, so the test
    // stands the dir up itself.
    std::fs::create_dir_all(&dir).expect("mkdir ~/.clauth");
    let _incumbent = match crate::daemon::probe::claim_singleton(&dir, false).expect("claim") {
        crate::daemon::probe::Claim::Active(lock) => lock,
        _ => panic!("an uncontended sandbox must yield an active claim"),
    };

    crate::daemon::serve(
        crate::daemon::StartMode::ExitIfRunning,
        Some(addr),
        &crate::daemon::api::tls::CertSource::Explicit(paths),
    )
    .expect("a redundant listener instance exits 0, not a bind error");
}

/// A failing `prepare` must leave the singleton UNCLAIMED: `--replace`
/// terminates the incumbent as part of claiming, so a certificate that dies in
/// the prepare step above the claim has to die without touching the incumbent
/// at all. The unit under test is the ORDER in `daemon::serve`, which no test
/// pinned: the certificate-failure test calls `prepare` directly and this file's
/// only other `serve` caller drives `ExitIfRunning` with a valid certificate.
///
/// Redundant with nothing: without the order, `--replace --listen` with a broken
/// cert is the round-2 blocker — the incumbent is reaped first and the host is
/// left with no daemon, no refresh, and no auto-switch.
#[test]
fn a_failing_prepare_leaves_the_incumbent_alive_under_replace() {
    let _home = HomeSandbox::new();
    // An empty cert dir: a present `tls.json` pointing there, so `prepare`
    // itself fails to load the certificate rather than skipping the listener.
    let empty = tempfile::tempdir().expect("tempdir");
    let tls_json = crate::profile::clauth_dir().expect("dir").join("tls.json");
    std::fs::create_dir_all(tls_json.parent().expect("has parent")).expect("mkdir");
    std::fs::write(
        &tls_json,
        serde_json::json!({ "schema": 1, "cert_dir": empty.path() }).to_string(),
    )
    .expect("write tls.json");
    // A concrete port the incumbent holds, so a bind misplaced above the claim
    // would fail here for a different reason.
    let incumbent_port = std::net::TcpListener::bind("127.0.0.1:0").expect("bind");
    let addr = incumbent_port.local_addr().expect("addr");
    let dir = crate::profile::clauth_dir().expect("dir");
    let incumbent = match crate::daemon::probe::claim_singleton(&dir, false).expect("claim") {
        crate::daemon::probe::Claim::Active(lock) => lock,
        _ => panic!("an uncontended sandbox must yield an active claim"),
    };

    let Err(err) = crate::daemon::serve(
        crate::daemon::StartMode::Replace,
        Some(addr),
        &crate::daemon::api::tls::CertSource::Lego,
    ) else {
        panic!("an unreadable certificate must fail serve, not pass");
    };
    assert!(
        format!("{err:#}").contains(&empty.path().display().to_string()),
        "the failure names the path the operator has to fix: {err:#}"
    );

    // THE assertion: the incumbent is still the holder. Under the order-flip
    // regression this reads Redundant only via the incumbent FLOCK staying
    // held: the incumbent here is this test's own process, which does not run
    // as `clauth daemon` by argv, so `claim_by_replacing` would bail at the
    // pid identity guard (an `Err`, never a signal) and the flock is never
    // released either way. The pin's true red is the error-text assert above:
    // under the regression the bind fails above the claim, `serve` returns
    // `Err` naming the bind, and this assert never even runs. It stays as the
    // second-order guard it is, holding whenever the first one has already
    // reddened the run.
    let second = crate::daemon::probe::claim_singleton(&dir, false).expect("second claim");
    assert!(
        matches!(second, crate::daemon::probe::Claim::Redundant),
        "the failing prepare must leave the singleton held by the incumbent: {second:?}"
    );
    drop(incumbent);
}

// The token mint sits below the singleton claim: a `--listen` start that dies
// on TLS preparation, or yields as redundant, must never write
// `auth_token.json` — replacing a damaged file there revokes every client of
// the running daemon from a start that served nothing. The byte comparisons
// assert through `assert!` on purpose: a red must not print token bytes.

/// `~/.clauth/auth_token.json` inside the sandbox.
fn token_file() -> std::path::PathBuf {
    crate::profile::clauth_dir()
        .expect("dir")
        .join("auth_token.json")
}

/// Seed a well-formed fixture token — the identity a running incumbent was
/// spawned with and its clients hold. Synthetic fixture bytes only; a bearer is
/// a password, so nothing here renders one.
fn seed_token(path: &Path, token: &str) {
    crate::profile::mkdir_700(path.parent().expect("token parent")).expect("mkdir token parent");
    std::fs::write(
        path,
        serde_json::json!({
            "schema": 1,
            "token": token,
            "created_at": "synthetic-fixture",
            "tier": "control",
        })
        .to_string(),
    )
    .expect("write the token fixture");
}

/// A health request answered by the INCUMBENT's context. Routes read the token
/// file per request (`token::current_or`), so a replacement on disk is what
/// flips which bearer verifies — the revocation these tests pin.
fn health_status(ctx: &ApiContext, bearer: &str) -> u16 {
    routes::handle(
        ctx,
        &http::Request {
            method: "GET".to_string(),
            path: "/api/v1/health".to_string(),
            query: String::new(),
            bearer: Some(bearer.to_string()),
            if_none_match: None,
            body: Vec::new(),
            keep_alive: false,
        },
    )
    .status
}

/// Hold the singleton lock the way a running daemon does: a real flock claimed
/// in this process, released when the test ends. `serve` would create the dir
/// itself; the claim has to run first, so this stands it up.
fn incumbent_claim() -> crate::daemon::probe::DaemonLock {
    let dir = crate::profile::clauth_dir().expect("dir");
    std::fs::create_dir_all(&dir).expect("mkdir ~/.clauth");
    match crate::daemon::probe::claim_singleton(&dir, false).expect("claim") {
        crate::daemon::probe::Claim::Active(lock) => lock,
        other => panic!("an uncontended sandbox must yield an active claim: {other:?}"),
    }
}

/// Certificates that cannot be read, so `serve` fails in TLS preparation — the
/// arm whose failure must not cost the incumbent its clients.
fn unreadable_certs(root: &Path) -> crate::daemon::api::tls::CertSource {
    crate::daemon::api::tls::CertSource::Explicit(crate::daemon::api::tls::CertPaths {
        cert: root.join("missing.crt"),
        issuer: None,
        key: root.join("missing.key"),
    })
}

/// A damaged `auth_token.json` must survive a contender whose certificate
/// cannot be read. The mint used to run beside that certificate read, above the
/// singleton claim, so the contender replaced the file on its way out and every
/// client of the running daemon went 401 — the pin is the file's bytes and the
/// incumbent's auth flip, not just the error.
#[test]
fn a_tls_failed_start_leaves_a_damaged_token_file_untouched() {
    let _home = HomeSandbox::new();
    let path = token_file();
    seed_token(&path, TOKEN);
    let incumbent = ctx();
    let _lock = incumbent_claim();
    // Held by the test, so a bind misplaced above the claim would fail on the
    // port before reaching the arm under test.
    let held = std::net::TcpListener::bind("127.0.0.1:0").expect("bind held port");
    let addr = held.local_addr().expect("addr");
    assert_eq!(health_status(&incumbent, TOKEN), 200);
    std::fs::write(&path, b"not json").expect("damage the token file");
    assert_eq!(
        health_status(&incumbent, TOKEN),
        200,
        "damaged disk state alone must fall back to the incumbent's spawn token"
    );

    let err = crate::daemon::serve(
        crate::daemon::StartMode::ExitIfRunning,
        Some(addr),
        &unreadable_certs(_home.home()),
    )
    .expect_err("the unreadable certificate must fail the contender");
    assert!(
        format!("{err:#}").contains("failed to read the TLS certificate"),
        "the failure must be TLS preparation, not something later: {err:#}"
    );
    assert!(
        std::fs::read(&path).expect("read the damaged file") == b"not json",
        "a failed contender must leave the damaged token file byte-identical"
    );
    assert_eq!(
        health_status(&incumbent, TOKEN),
        200,
        "the incumbent's clients must still verify after the failed start"
    );
}

/// No token file at all must stay that way: a file minted by a start that never
/// serves is a credential nobody asked for.
#[test]
fn a_tls_failed_start_mints_no_token_when_none_exists() {
    let _home = HomeSandbox::new();
    let path = token_file();
    seed_token(&path, TOKEN);
    let incumbent = ctx();
    let _lock = incumbent_claim();
    let held = std::net::TcpListener::bind("127.0.0.1:0").expect("bind held port");
    let addr = held.local_addr().expect("addr");
    std::fs::remove_file(&path).expect("remove the token file");

    let err = crate::daemon::serve(
        crate::daemon::StartMode::ExitIfRunning,
        Some(addr),
        &unreadable_certs(_home.home()),
    )
    .expect_err("the unreadable certificate must fail the contender");
    assert!(
        format!("{err:#}").contains("failed to read the TLS certificate"),
        "{err:#}"
    );
    assert!(
        !path.exists(),
        "a contender that never served must not mint a token file"
    );
    assert_eq!(health_status(&incumbent, TOKEN), 200);
}

/// The redundant exit is a one-line yield to the holder — and under the old
/// order the contender's only durable action was still a token replacement:
/// the mint ran above the claim, before the contender knew it was redundant.
#[test]
fn a_redundant_start_leaves_a_damaged_token_file_untouched() {
    let _home = HomeSandbox::new();
    let certdir = tempfile::tempdir_in(_home.home()).expect("cert fixture dir");
    let Some((paths, _ca)) = generate_chain(certdir.path()).expect("fixture") else {
        eprintln!(
            "SKIPPED a_redundant_start_leaves_a_damaged_token_file_untouched: \
             openssl is not usable here"
        );
        return;
    };
    let path = token_file();
    seed_token(&path, TOKEN);
    let incumbent = ctx();
    let _lock = incumbent_claim();
    let held = std::net::TcpListener::bind("127.0.0.1:0").expect("bind held port");
    let addr = held.local_addr().expect("addr");
    assert_eq!(health_status(&incumbent, TOKEN), 200);
    std::fs::write(&path, b"not json").expect("damage the token file");

    let lines = crate::logline::LogLines::new();
    let _capture = lines.capture_here();
    crate::daemon::serve(
        crate::daemon::StartMode::ExitIfRunning,
        Some(addr),
        &crate::daemon::api::tls::CertSource::Explicit(paths),
    )
    .expect("a redundant contender exits 0");
    assert!(
        lines
            .snapshot()
            .iter()
            .any(|line| line.contains("already running")),
        "the contender must have reached the redundant-claim branch"
    );
    assert!(
        std::fs::read(&path).expect("read the damaged file") == b"not json",
        "a redundant start must leave the damaged token file byte-identical"
    );
    assert_eq!(health_status(&incumbent, TOKEN), 200);
}

// ── a standby's certificate across the park (#63 T19) ────────────────────────
//
// A standby parks with the config `prepare` built ABOVE the claim, and the
// park is unbounded by design (the launchd/systemd pairing), so whatever the
// certificate files become during it used to be invisible until the daemon's
// next restart. The pins below drive the real standby arm of `serve` — an
// incumbent holds the singleton, the contender parks, the incumbent exits —
// with the certificate mutation landing MID-PARK, exactly where a `lego renew`
// lands.

/// Drive one `--standby` start against a test-held singleton: spawn `serve` on
/// a thread, wait until it has parked, run `mutate` while it is parked, then
/// release the incumbent and return `serve`'s verdict. The listen port is held
/// by the test for the whole drive, so a start that wrongly proceeds past its
/// certificate lands on the bind's own error instead of a live listener — the
/// one outcome the pins must never produce.
fn drive_parked_standby(
    certs: crate::daemon::api::tls::CertSource,
    mutate: impl FnOnce(),
) -> anyhow::Result<()> {
    let incumbent = incumbent_claim();
    let held = std::net::TcpListener::bind("127.0.0.1:0").expect("bind the held port");
    let addr = held.local_addr().expect("held addr");
    let parked = std::thread::spawn(move || {
        crate::daemon::serve(crate::daemon::StartMode::Standby, Some(addr), &certs)
    });

    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
    while !crate::daemon::probe::standby_waiting() {
        assert!(
            !parked.is_finished(),
            "serve settled before parking; the certificate fixture never reached the park"
        );
        assert!(
            std::time::Instant::now() < deadline,
            "the standby never parked within 10s"
        );
        std::thread::sleep(std::time::Duration::from_millis(5));
    }

    mutate();

    drop(incumbent); // the incumbent exits: the parked contender promotes

    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
    while !parked.is_finished() {
        assert!(
            std::time::Instant::now() < deadline,
            "the promoted standby did not settle within 10s"
        );
        std::thread::sleep(std::time::Duration::from_millis(5));
    }
    parked
        .join()
        .expect("the standby serve thread must not panic")
}

/// The certificate file is deleted while the contender parks — the shape of a
/// renewal mid-rewrite. The promotion must FAIL: `serve` returns an error
/// naming the certificate before any listener exists and before the token
/// mint, because a daemon that promoted anyway would look healthy while
/// serving the stale identity to every client.
#[test]
fn a_promoted_standby_whose_certificate_vanished_fails_before_listening() {
    let _home = HomeSandbox::new();
    let certdir = tempfile::tempdir_in(_home.home()).expect("cert fixture dir");
    let Some((paths, _ca)) = generate_chain(certdir.path()).expect("fixture") else {
        eprintln!(
            "SKIPPED a_promoted_standby_whose_certificate_vanished_fails_before_listening: \
             openssl is not usable here"
        );
        return;
    };
    let cert = paths.cert.clone();
    let verdict =
        drive_parked_standby(crate::daemon::api::tls::CertSource::Explicit(paths), || {
            std::fs::remove_file(&cert).expect("remove the parked-away certificate")
        });
    let Err(err) = verdict else {
        panic!("a promotion whose certificate replacement is unreadable must fail the start");
    };
    assert!(
        format!("{err:#}").contains("failed to read the TLS certificate"),
        "the failure must be the post-promotion reload, not the bind or anything later: {err:#}"
    );
    assert!(
        !token_file().exists(),
        "a promotion that never served must not mint a token"
    );
}

/// A corrupted replacement (a torn write, PEM that parses to no certificate)
/// fails the promotion exactly like a missing one: loudly, before the
/// listener. Pre-fix this promoted silently and kept serving the stale
/// certificate.
#[test]
fn a_promoted_standby_whose_certificate_corrupted_fails_before_listening() {
    let _home = HomeSandbox::new();
    let certdir = tempfile::tempdir_in(_home.home()).expect("cert fixture dir");
    let Some((paths, _ca)) = generate_chain(certdir.path()).expect("fixture") else {
        eprintln!(
            "SKIPPED a_promoted_standby_whose_certificate_corrupted_fails_before_listening: \
             openssl is not usable here"
        );
        return;
    };
    let cert = paths.cert.clone();
    let verdict =
        drive_parked_standby(crate::daemon::api::tls::CertSource::Explicit(paths), || {
            std::fs::write(&cert, "not a certificate: a torn renewal write")
                .expect("corrupt the replacement")
        });
    let Err(err) = verdict else {
        panic!("a promotion whose certificate replacement cannot be parsed must fail the start");
    };
    let msg = format!("{err:#}");
    assert!(
        msg.contains(&format!("{SERVER_NAME}.crt")),
        "the failure must name the file the operator has to fix: {msg}"
    );
    assert!(
        !msg.contains("failed to bind"),
        "the failure must come from the reload, not the bind — a reload after the bind would \
         mean a listener existed: {msg}"
    );
    assert!(
        !token_file().exists(),
        "a promotion that never served must not mint a token"
    );
}

/// The control, green before and after the fix: a plain start reads the
/// certificate exactly once, above the claim, so whatever lands on disk AFTER
/// `prepare` changes nothing about what it serves. What can red here is that
/// one read's product — a config deferring any part of the identity to
/// handshake time. `serve`'s plain arm (a won claim run through to
/// `serve_prepared`) is not driven anywhere in this suite — every call site
/// yields, dies pre-claim, or parks — so this seam is the plain path's only
/// pin.
#[test]
fn a_plain_start_serves_exactly_the_certificate_it_read_above_the_claim() {
    let _home = HomeSandbox::new();
    let certdir = tempfile::tempdir_in(_home.home()).expect("cert fixture dir");
    let Some((paths, ca_crt)) = generate_chain(certdir.path()).expect("fixture") else {
        eprintln!(
            "SKIPPED a_plain_start_serves_exactly_the_certificate_it_read_above_the_claim: \
             openssl is not usable here"
        );
        return;
    };
    let ctx = ctx();
    let listener = std::net::TcpListener::bind(("127.0.0.1", 0)).expect("bind");
    let addr = listener.local_addr().expect("addr");
    let port = addr.port();
    let cert = paths.cert.clone();
    let prepared = super::prepare(addr, &crate::daemon::api::tls::CertSource::Explicit(paths))
        .expect("prepare reads the valid certificate");

    // The one read has happened; whatever the files become now must not matter.
    std::fs::write(&cert, "ruined after the one read").expect("ruin the certificate file");

    let tls = std::sync::Arc::clone(&prepared.tls_config);
    std::thread::scope(|scope| {
        scope.spawn(move || {
            // Bounded for the same reason as the standby pin's worker: a leg
            // that reddens before connecting must fail, not hang the scope.
            listener
                .set_nonblocking(true)
                .expect("nonblocking listener");
            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
            while std::time::Instant::now() < deadline {
                match listener.accept() {
                    Ok((stream, peer)) => {
                        stream.set_nonblocking(false).expect("blocking stream");
                        serve_connection(stream, peer, &tls, &ctx, Limits::DEFAULT);
                        break;
                    }
                    Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                        std::thread::sleep(std::time::Duration::from_millis(5));
                    }
                    Err(_) => break,
                }
            }
        });
        let client = client_config(&ca_crt).expect("client config");
        let answer = round_trip(
            port,
            &client,
            &format!(
                "GET /api/v1/health HTTP/1.1\r\nHost: {SERVER_NAME}\r\n\
                 Authorization: Bearer {TOKEN}\r\nConnection: close\r\n\r\n"
            ),
        )
        .expect("the certificate read once still serves");
        assert!(
            answer.starts_with("HTTP/1.1 200 OK\r\n"),
            "a plain start serves exactly what it read: {answer}"
        );
    });
}

/// The other control: a standby whose INITIAL certificate is unreadable still
/// dies in the pre-claim read and never takes the standby slot — the promotion
/// reload must not move the first read below the claim.
#[test]
fn a_standby_with_an_unreadable_initial_certificate_exits_before_claiming() {
    let _home = HomeSandbox::new();
    let incumbent = incumbent_claim();
    let held = std::net::TcpListener::bind("127.0.0.1:0").expect("bind held port");
    let addr = held.local_addr().expect("addr");

    let Err(err) = crate::daemon::serve(
        crate::daemon::StartMode::Standby,
        Some(addr),
        &unreadable_certs(_home.home()),
    ) else {
        panic!("an unreadable initial certificate must fail a standby start");
    };
    assert!(
        format!("{err:#}").contains("failed to read the TLS certificate"),
        "the failure must be the pre-claim read: {err:#}"
    );
    assert!(
        !crate::daemon::probe::standby_waiting(),
        "a start that died on its initial certificate must not hold the standby slot"
    );
    drop(incumbent);
}

/// The fix's happy half: the identity that lands during the park is what the
/// promoted daemon serves. The renewal is a whole second identity — a new CA
/// and a new leaf — copied over the same paths MID-PARK, so serving the
/// pre-park config and serving the renewal differ by WHICH CA verifies the
/// handshake. Drives the standby sequence itself at the seam —
/// `claim_singleton` + `stand_by` for the park and promotion, then
/// `reload_certificate`, then `serve_connection` with the config the reload
/// left in `Prepared`. `serve`'s own standby arm is never entered here; that
/// the arm calls this reload is witnessed by the two failure pins above,
/// whose reds name the reload.
#[test]
fn a_promoted_standby_serves_the_certificate_that_landed_during_its_park() {
    let _home = HomeSandbox::new();
    let dir_a = tempfile::tempdir_in(_home.home()).expect("cert dir A");
    let dir_b = tempfile::tempdir_in(_home.home()).expect("cert dir B");
    let Some((paths_a, ca_a)) = generate_chain(dir_a.path()).expect("fixture A") else {
        eprintln!(
            "SKIPPED a_promoted_standby_serves_the_certificate_that_landed_during_its_park: \
             openssl is not usable here"
        );
        return;
    };
    let Some((paths_b, ca_b)) = generate_chain(dir_b.path()).expect("fixture B") else {
        eprintln!(
            "SKIPPED a_promoted_standby_serves_the_certificate_that_landed_during_its_park: \
             openssl is not usable here"
        );
        return;
    };
    let client_old = client_config(&ca_a).expect("client for the parked-away CA");
    let ctx = ctx();
    let listener = std::net::TcpListener::bind(("127.0.0.1", 0)).expect("bind");
    let addr = listener.local_addr().expect("addr");
    let port = addr.port();
    // The same explicit source a `--cert`/`--key` start builds, twice: once
    // for the pre-claim read, once for the post-promotion reload.
    let source = || {
        crate::daemon::api::tls::CertSource::Explicit(crate::daemon::api::tls::CertPaths {
            cert: paths_a.cert.clone(),
            issuer: None,
            key: paths_a.key.clone(),
        })
    };

    // serve's pre-claim read: the parked-away identity is valid.
    let mut prepared =
        super::prepare(addr, &source()).expect("prepare reads the valid parked-away certificate");

    // serve's standby arm: take the slot, park, promote on the holder's exit.
    let incumbent = incumbent_claim();
    let dir = crate::profile::clauth_dir().expect("dir");
    let crate::daemon::probe::Claim::Standby(slot) =
        crate::daemon::probe::claim_singleton(&dir, true).expect("claim")
    else {
        panic!("the second instance takes the one standby slot");
    };
    let parked = {
        let dir = dir.clone();
        std::thread::spawn(move || crate::daemon::stand_by(&dir, slot))
    };
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
    while !crate::daemon::probe::standby_waiting() {
        assert!(
            std::time::Instant::now() < deadline,
            "the standby never parked within 10s"
        );
        std::thread::sleep(std::time::Duration::from_millis(5));
    }
    // The renewal lands mid-park: same paths, a different CA's identity.
    std::fs::copy(&paths_b.cert, &paths_a.cert).expect("renew the leaf");
    std::fs::copy(&paths_b.key, &paths_a.key).expect("renew the key");
    drop(incumbent); // the incumbent exits: promotion
    let _promoted = parked
        .join()
        .expect("the stand_by thread must not panic")
        .expect("the standby promotes once the holder exits");

    // serve's post-promotion reload, then the config it would serve.
    prepared
        .reload_certificate(&source())
        .expect("the renewed certificate reloads");

    let renewed_tls = std::sync::Arc::clone(&prepared.tls_config);
    std::thread::scope(|scope| {
        scope.spawn(move || {
            // Two connections: the renewed client, then the stale one. Bounded,
            // because on a reddening leg the second connection never happens
            // and a blocking accept would hold the scope — and the verdict —
            // hostage past the assertion that already failed.
            listener
                .set_nonblocking(true)
                .expect("nonblocking listener");
            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
            let mut served = 0;
            while served < 2 && std::time::Instant::now() < deadline {
                match listener.accept() {
                    Ok((stream, peer)) => {
                        stream.set_nonblocking(false).expect("blocking stream");
                        serve_connection(stream, peer, &renewed_tls, &ctx, Limits::DEFAULT);
                        served += 1;
                    }
                    Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                        std::thread::sleep(std::time::Duration::from_millis(5));
                    }
                    Err(_) => break,
                }
            }
        });

        let renewed_client = client_config(&ca_b).expect("client for the renewed CA");
        let answer = round_trip(
            port,
            &renewed_client,
            &format!(
                "GET /api/v1/health HTTP/1.1\r\nHost: {SERVER_NAME}\r\n\
                 Authorization: Bearer {TOKEN}\r\nConnection: close\r\n\r\n"
            ),
        )
        .expect("a handshake against the renewed identity");
        assert!(
            answer.starts_with("HTTP/1.1 200 OK\r\n"),
            "the promoted daemon must serve under the renewed identity: {answer}"
        );

        // The stale identity must be gone from the listener: a client trusting
        // only the pre-park CA cannot even complete the handshake.
        let mut stale = Session::connect(port, &client_old).expect("tcp connect");
        assert!(
            stale
                .send("GET /api/v1/health HTTP/1.1\r\nHost: x\r\n\r\n")
                .is_err(),
            "the parked-away identity must not verify against the renewed listener"
        );
    });
}

/// The control, green both before and after the mint moves: a HEALTHY token is
/// never rewritten by any start, because reading a valid token never writes.
/// If this reddens, the mint stopped reading before writing.
#[test]
fn a_tls_failed_start_leaves_a_healthy_token_untouched() {
    let _home = HomeSandbox::new();
    let path = token_file();
    seed_token(&path, TOKEN);
    let incumbent = ctx();
    let _lock = incumbent_claim();
    let held = std::net::TcpListener::bind("127.0.0.1:0").expect("bind held port");
    let addr = held.local_addr().expect("addr");
    let before = std::fs::read(&path).expect("read the healthy file");
    assert_eq!(health_status(&incumbent, TOKEN), 200);

    let err = crate::daemon::serve(
        crate::daemon::StartMode::ExitIfRunning,
        Some(addr),
        &unreadable_certs(_home.home()),
    )
    .expect_err("the unreadable certificate must fail the contender");
    assert!(
        format!("{err:#}").contains("failed to read the TLS certificate"),
        "{err:#}"
    );
    assert!(
        std::fs::read(&path).expect("read the token file") == before,
        "a healthy token must stay byte-identical across a failed start"
    );
    assert_eq!(health_status(&incumbent, TOKEN), 200);
}
